    'quebrar-pagina-dentro': { nomeCss: 'page-break-inside', descricao: 'Ajusta as quebras de página dentro do elemento atual.', documentacao: '# `quebrar-pagina-dentro`\nEsta propriedade se aplica a elementos de bloco que geram uma caixa e não se aplica a uma <divisao> vazia que não gere uma caixa.', exemploCodigo: 'divisao {\n  quebrar-pagina-dentro: auto;\n}' },
